// Shapes of the tables in rc_data.cpp (generated by tools/rc2qt.py from upstream Rsrc.rc).
#pragma once
#include <vector>

namespace rc {

struct ControlDef {
    const char *kind;    // LTEXT, CTEXT, RTEXT, GROUPBOX, PUSHBUTTON, DEFPUSHBUTTON, EDITTEXT, COMBOBOX, LISTBOX, CONTROL, ...
    const char *text;
    int id;
    int x, y, w, h;      // dialog units
    const char *style;   // Win32 style flags as written in the script ("BS_AUTOCHECKBOX | WS_TABSTOP")
    const char *exstyle;
    const char *cls;     // window class of a CONTROL ("Button", "Static", ...)
};

struct DialogDef {
    const char *name;
    const char *caption;
    int x, y, w, h;
    const char *font;
    int font_size;
    const char *style;
    std::vector<ControlDef> controls;
};

struct MenuItem {
    const char *text;
    int id;
    enum Kind { Popup, Begin, End, Item, Separator, Eof } kind;
};

struct AccelDef {
    const char *key;     // "C", "VK_F1", ...
    int id;
    bool ctrl, alt, shift;
};

extern const DialogDef kDialogs[];
extern const MenuItem kMenu[];
extern const AccelDef kAccel[];

}  // namespace rc
